import React from "react";
import Card from "./Card";
import SmallCard from "./SmallCard";

export default function Home() {
  const experiences = [
    {
      image: "/images/aws.png",
      title: "Amazon Web Services (May 2024 - Aug 2024)",
      description: "Software Development Engineer Intern, S3 Glacier",
      link: "https://aws.amazon.com/s3/glacier/",
      linkText: "Visit Here",
    },
    {
      image: "/images/primarius.png",
      title: "Primarius Technology (May 2023 - Aug 2023)",
      description: "Research Intern, Parallel Direct Sparse Matrix Solver",
      link: "https://www.primarius-tech.com/en.php",
      linkText: "Visit Here",
    },
    {
      image: "/images/roadflex.png",
      title: "RoadFlex (2022)",
      description: "Head of Credit Underwriting",
      link: "https://www.roadflex.com/",
      linkText: "Visit Here",
    },
  ];

  const projects = [
    {
      image: "/images/research.png",
      title: "Zero-Shot Reference-Based Image Editing Without Training or Guidance",
      description: "Kelvin Li, Jorge Diaz Chao",
      link: "/pdf/zero-shot.pdf",
      linkText: "View PDF",
    },
    {
      image: "/images/victoris.png",
      title: "Victoris",
      description: "Founder, Education platform",
    },
  ];

  const smallProjects = [
    { image: "/images/cs180-1.png", title: "CS180 Project 1", link: "#" },
    { image: "/images/cs180-2.png", title: "CS180 Project 2", link: "#" },
    { image: "/images/website.png", title: "Personal Website", link: "#" },
    { image: "/images/other-project.png", title: "Other Project", link: "#" },
  ];

  return (
    <div className="min-h-screen bg-gradient-to-b from-gray-100 to-white flex flex-col items-center px-6 font-inter">
      {/* Hero Section */}
      <div className="max-w-3xl text-center mt-16">
        <h1 className="text-5xl font-extrabold bg-clip-text text-transparent bg-gradient-to-r from-blue-500 to-purple-600">
          Kelvin Li
        </h1>
        <p className="text-gray-600 mt-3 text-lg">
          Hi, I am an undergraduate at UC Berkeley, studying EECS and Mathematics.
        </p>
        <div className="mt-5 flex justify-center space-x-6">
          <a href="https://linkedin.com/in/kelvinli" className="text-blue-500 hover:underline font-medium">LinkedIn</a>
          <a href="https://github.com/kelvinli" className="text-blue-500 hover:underline font-medium">GitHub</a>
          <a href="mailto:kelvin.li@email.com" className="text-blue-500 hover:underline font-medium">Email</a>
        </div>
      </div>

      {/* Experience Cards - First Row */}
      <div className="mt-16 grid grid-cols-1 md:grid-cols-3 gap-8 max-w-6xl">
        {experiences.map((exp, index) => (
          <Card key={index} {...exp} />
        ))}
      </div>

      {/* Research & Victoris - Second Row */}
      <div className="mt-16 grid grid-cols-1 md:grid-cols-2 gap-8 max-w-6xl">
        {projects.map((project, index) => (
          <Card key={index} {...project} />
        ))}
      </div>

      {/* Divider */}
      <div className="w-36 border-b-4 border-gray-300 my-16"></div>

      {/* Small Projects Title */}
      <h2 className="text-2xl font-bold text-gray-800">Other Projects</h2>

      {/* Small Projects - Grid */}
      <div className="mt-8 grid grid-cols-1 md:grid-cols-4 gap-6 max-w-6xl">
        {smallProjects.map((proj, index) => (
          <SmallCard key={index} {...proj} />
        ))}
      </div>

      {/* Footer */}
      <div className="mt-16 text-sm text-gray-500">
        © 2025 Kelvin Li • Built with React & Tailwind CSS
      </div>
    </div>
  );
}
